CREATE TABLE "public"."headwords" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "slug"            text                     NOT NULL,
  "script_latin"    text,
  "script_tifinagh" text,
  "script_arabic"   text,
  "created_at"      timestamp with time zone DEFAULT now(),
  "updated_at"      timestamp with time zone DEFAULT now(),
  CONSTRAINT "headwords_pkey" PRIMARY KEY (id),
  CONSTRAINT "headwords_slug_key" UNIQUE (slug)
);

CREATE INDEX headwords_script_latin_trgm_idx ON public.headwords USING gin (script_latin public.gin_trgm_ops);

CREATE TRIGGER set_timestamp_headwords
  BEFORE UPDATE ON public.headwords
  FOR EACH ROW
  EXECUTE FUNCTION public.update_timestamp();

REVOKE ALL ON SEQUENCE "public"."headwords_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."headwords_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."headwords_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."headwords_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."headwords_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."headwords_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."headwords_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."headwords_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."headwords" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."headwords" TO "service_role";

REVOKE ALL ON TABLE "public"."headwords" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."headwords" TO "postgres";
